const byId = new Map();
for (const group of groups) {
  const sources = [{ label: group.source.includes('openstreetmap.org') ? 'OpenStreetMap — ობიექტი' : 'ოფიციალური წყარო', url: group.source }, ...(group.sources || [])];
  const value = Object.freeze({ key: group.key, title: group.title, description: group.description, highlights: group.highlights, sources,
    website: group.website || '', reviewedAt: '2026-10-19', scope: group.scope || (group.ids.length > 1 ? 'institution' : 'place'),
    posts: group.posts.map(([title, body, sourceUrl], index) => ({ id: `${group.key}-${index + 1}`, title, body, sourceUrl: sourceUrl || group.source, authorType: 'directory', reviewedAt: '2026-10-19' })),
  });
  for (const id of group.ids) {
    if (byId.has(id)) throw new Error(`Duplicate curated editorial place: ${id}`);
    byId.set(id, value);
  }
}

export const PLACE_EDITORIAL_IDS = Object.freeze([...byId.keys()]);
export const PLACE_EDITORIAL_GROUP_COUNT = groups.length;
export function getPlaceEditorial(place) {
  const id = typeof place === 'string' ? place : place?.id;
  return byId.get(id) || null;
}
